{"command": "python3 <<'PY'
import subprocess, os, tempfile
def run(args, env=None):
    e=os.environ.copy()
    if env: e.update(env)
    p=subprocess.run(["./executable"]+args, capture_output=True, env=e, timeout=10)
    return p
# Test search order
for exts in [["yaml","json"], ["yaml","toml"], ["yml","yaml"], ["json","toml"]]:
    tmpdir=tempfile.mkdtemp()
    os.makedirs(f"{tmpdir}/ov", exist_ok=True)
    for ext in exts:
        if ext in ["yaml","yml"]:
            open(f"{tmpdir}/ov/config.{ext}","w").write(f"Mode:\n  mode_{ext}:\n    Header: 1\n")
        elif ext=="json":
            open(f"{tmpdir}/ov/config.json","w").write('{"Mode": {"mode_json": {"Header": 1}}}')
        elif ext=="toml":
            open(f"{tmpdir}/ov/config.toml","w").write('[Mode.mode_toml]\nHeader=1\n')
    p=run(["--list-view-modes"], env={"XDG_CONFIG_HOME": tmpdir})
    print(exts, repr(p.stdout))
    p=run(["--debug","--list-view-modes"], env={"XDG_CONFIG_HOME": tmpdir})
    print("  debug", repr(p.stderr[:200]))
PY"}

