func loadConfig(cmd *cobra.Command) error {
	// Get config flag value and changed
	configVal, _ := cmd.Flags().GetString("config")
	// Need to check if flag was explicitly set with non-empty value
	// Use Lookup and Changed
	changed := false
	if f := cmd.Flags().Lookup("config"); f != nil {
		changed = f.Changed
	} else if f := cmd.PersistentFlags().Lookup("config"); f != nil {
		changed = f.Changed
	}
	// Also check inherited?
	// For subcommands, Flags() includes persistent, so Lookup should work
	debugVal := false
	if b, err := cmd.Flags().GetBool("debug"); err == nil {
		debugVal = b
	}
	if changed && configVal != "" {
		return loadExplicitConfig(configVal, debugVal)
	}
	// Default search
	return loadDefaultConfig(debugVal)
}

func loadExplicitConfig(file string, debug bool) error {
	// Check existence via Stat? Use os.Stat to distinguish not found?
	// First try Stat
	_, statErr := os.Stat(file)
	if statErr != nil && os.IsNotExist(statErr) {
		msg := fmt.Sprintf("failed to read config file: open %s: no such file or directory", file)
		fmt.Fprintln(os.Stderr, msg)
		if debug {
			fmt.Fprintln(os.Stderr, "Using config file:", file)
		}
		configModes = nil
		return nil
	}
	// Get ext
	ext := ""
	if dot := strings.LastIndex(file, "."); dot != -1 {
		// ensure dot after last slash
		slash := strings.LastIndex(file, "/")
		if dot > slash {
			ext = file[dot+1:]
		}
	}
	// Handle directory with ext? Stat succeeded and isDir will be caught in ReadFile?
	// Check supported
	supported := map[string]bool{"yaml": true, "yml": true, "json": true, "toml": true}
	if !supported[ext] {
		msg := fmt.Sprintf("failed to read config file: Unsupported Config Type %q", ext)
		fmt.Fprintln(os.Stderr, msg)
		if debug {
			fmt.Fprintln(os.Stderr, "Using config file:", file)
		}
		configModes = nil
		return nil
	}
	// Try to read
	data, err := os.ReadFile(file)
	if err != nil {
		// err already contains "open ..." or "read ..." prefix
		msg := fmt.Sprintf("failed to read config file: %s", err.Error())
		fmt.Fprintln(os.Stderr, msg)
		if debug {
			fmt.Fprintln(os.Stderr, "Using config file:", file)
		}
		configModes = nil
		return nil
	}
	// Parse
	modes, perr := parseConfigData(data, ext)
	if perr != nil {
		// perr is already full message? For parse errors, need prefix "failed to read config file: While parsing config: ..."
		// For decode errors, no prefix? Handle in parse function
		// parseConfigData returns (modes, warningMsg, isDecodeError?)
		// Instead, handle here: if perr is parse error, prefix; if decode, no prefix?
		// For simplicity, parseConfigData returns error string already formatted?
		// Let's have it return formatted warning to print
		fmt.Fprintln(os.Stderr, perr.Error())
		if debug {
			fmt.Fprintln(os.Stderr, "Using config file:", file)
		}
		configModes = nil
		return nil
	}
	configModes = modes
	if debug {
		fmt.Fprintln(os.Stderr, "Using config file:", file)
	}
	return nil
}

func loadDefaultConfig(debug bool) error {
	dir := ""
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		dir = filepath.Join(xdg, "ov")
	} else {
		home := os.Getenv("HOME")
		if home == "" {
			home = "/home/agent"
		}
		dir = filepath.Join(home, ".config", "ov")
	}
	// Search order: json, toml, yaml, yml (to match observed json first)
	order := []string{"json", "toml", "yaml", "yml"}
	var found string
	for _, ext := range order {
		p := filepath.Join(dir, "config."+ext)
		st, err := os.Stat(p)
		if err == nil && !st.IsDir() {
			found = p
			break
		}
	}
	if found == "" {
		// Not found
		if debug {
			fmt.Fprintf(os.Stderr, "failed to read config file: Config File \"config\" Not Found in \"[%s]\"\n", dir)
			fmt.Fprintln(os.Stderr, "config file not found")
		}
		configModes = nil
		return nil
	}
	// Found: try to read and parse, but warnings? For default found, parse errors warn even without debug? As observed.
	data, err := os.ReadFile(found)
	if err != nil {
		msg := fmt.Sprintf("failed to read config file: %s", err.Error())
		fmt.Fprintln(os.Stderr, msg)
		if debug {
			fmt.Fprintln(os.Stderr, "Using config file:", found)
		}
		configModes = nil
		return nil
	}
	ext := strings.TrimPrefix(filepath.Ext(found), ".")
	modes, perr := parseConfigData(data, ext)
	if perr != nil {
		fmt.Fprintln(os.Stderr, perr.Error())
		if debug {
			fmt.Fprintln(os.Stderr, "Using config file:", found)
		}
		configModes = nil
		return nil
	}
	configModes = modes
	if debug {
		fmt.Fprintln(os.Stderr, "Using config file:", found)
	}
	return nil
}

func parseConfigData(data []byte, ext string) ([]string, error) {
	// Returns modes or error (error already formatted for stderr? For parse errors, need "failed to read config file: While parsing config: ..." but caller adds prefix? Actually caller for explicit adds prefix? Let's handle here: return error with full prefix for parse, without prefix for decode?
	// For simplicity, return error with appropriate full message (including "failed..." or "decoding..." as needed), caller just prints err.Error().
	var raw map[string]interface{}
	var err error
	switch ext {
	case "yaml", "yml":
		// Use yaml.v3
		var m map[string]interface{}
		dec := yaml.NewDecoder(bytes.NewReader(data))
		// yaml.v3 strict? Just unmarshal first doc?
		// Use Unmarshal to handle?
		if err = yaml.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("failed to read config file: While parsing config: %s", err.Error())
		}
		raw = m
	case "json":
		var m map[string]interface{}
		if err = json.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("failed to read config file: While parsing config: %s", err.Error())
		}
		raw = m
	case "toml":
		var m map[string]interface{}
		if err = toml.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("failed to read config file: While parsing config: %s", err.Error())
		}
		raw = m
	default:
		return nil, fmt.Errorf("failed to read config file: Unsupported Config Type %q", ext)
	}
	// Extract Mode
	mv, ok := raw["Mode"]
	if !ok {
		return nil, nil
	}
	if mv == nil {
		return nil, nil
	}
	// Mode should be map
	switch v := mv.(type) {
	case map[string]interface{}:
		modes := make([]string, 0, len(v))
		for k := range v {
			modes = append(modes, k)
		}
		return modes, nil
	case map[interface{}]interface{}:
		modes := make([]string, 0)
		for k := range v {
			if s, ok := k.(string); ok {
				modes = append(modes, s)
			}
		}
		return modes, nil
	default:
		// Need to handle yaml decoded as map[interface{}]? Actually yaml.v3 decodes maps as map[string]interface{}? For Mode with list, mv will be []interface{}.
		// Check for slice -> decode error like original
		// Try to detect: if mv is slice, return decode error
		// Use reflection? Simplify: if not map, return decode error with same format as original for that case?
		// For "Mode:\n  - foo\n", mv is []interface{}{"foo"}
		// Original error: "decoding failed due to the following error(s):\n\n'Mode[0]' expected type 'map[string]oviewer.General', got unconvertible type 'string'\n"
		// We can return that exact string for that case, and generic for others?
		// Check type via reflection string?
		// For now, return generic decode error without prefix? Let's return same as original for slice case.
		// Use type switch with []interface{}
		if _, ok := mv.([]interface{}); ok {
			return nil, fmt.Errorf("decoding failed due to the following error(s):\n\n'Mode[0]' expected type 'map[string]oviewer.General', got unconvertible type 'string'")
		}
		// For other types (e.g., string, int), return generic? But unlikely.
		return nil, nil
	}
}

func runRoot(cmd *cobra.Command, args []string) error {
	// Priority: version > help-key > list > completion > force/cat
	// Help already handled via ErrHelp before here
	if flagVersion {
		fmt.Fprintln(cmd.OutOrStdout(), "ov version dev rev:HEAD")
		// Config warning already printed in PersistentPreRun, no extra
		return nil
	}
	if flagHelpKey {
		fmt.Fprint(cmd.OutOrStdout(), helpKey)
		return nil
	}
	if flagListViewModes {
		modes := append([]string{}, configModes...)
		modes = append(modes, "general")
		sort.Strings(modes)
		for _, m := range modes {
			fmt.Fprintln(cmd.OutOrStdout(), m)
		}
		return nil
	}
	// completion flag
	// Check if changed? Use Lookup Changed? If not changed or empty, skip
	compChanged := false
	if f := cmd.Flags().Lookup("completion"); f != nil {
		compChanged = f.Changed
	}
	if compChanged {
		if flagCompletion == "" {
			// empty means ignore, proceed to cat (like no flag)
		} else if flagCompletion == "bash" {
			fmt.Fprint(cmd.OutOrStdout(), scriptBash)
			return nil
		} else if flagCompletion == "zsh" {
			fmt.Fprint(cmd.OutOrStdout(), scriptZsh)
			return nil
		} else if flagCompletion == "fish" {
			fmt.Fprint(cmd.OutOrStdout(), scriptFish)
			return nil
		} else if flagCompletion == "powershell" {
			fmt.Fprint(cmd.OutOrStdout(), scriptPowershell)
			return nil
		} else {
			return fmt.Errorf("requires one of the arguments bash/zsh/fish/powershell")
		}
	}
	// force-screen?
	if flagForceScreen {
		return handleForceScreen(cmd, args)
	}
	// normal cat
	return handleCat(cmd, args)
}

func handleCat(cmd *cobra.Command, args []string) error {
	out := cmd.OutOrStdout()
	// args are files (after -- handling by cobra, args already excludes flags and --)
	if len(args) == 0 {
		// read stdin
		_, err := io.Copy(out, os.Stdin)
		return err
	}
	// only first file
	fname := args[0]
	f, err := os.Open(fname)
	if err != nil {
		return err
	}
	defer f.Close()
	// check if directory
	st, err := f.Stat()
	if err != nil {
		return err
	}
	if st.IsDir() {
		return fmt.Errorf("write /dev/stdout: copy_file_range: is a directory")
	}
	_, err = io.Copy(out, f)
	return err
}

func handleForceScreen(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		// Check stdin? Original reads stdin partially but errors. We just error.
		// To mimic race, we could try to read stdin with timeout? But deterministic: just error, no output.
		// However, to be closer, we could drain stdin? No, don't output.
		return fmt.Errorf("missing file")
	}
	fname := args[0]
	// Stat to check not found vs dir
	st, err := os.Stat(fname)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("'%s' not found", fname)
		}
		// other stat errors? Return open error?
		return err
	}
	if st.IsDir() {
		return fmt.Errorf("'%s' is a directory", fname)
	}
	// Try open (for permission etc.)
	f, err := os.Open(fname)
	if err != nil {
		return err
	}
	f.Close()
	// Try open /dev/tty
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return fmt.Errorf("Screen.Init(): open /dev/tty: no such device or address")
	}
	tty.Close()
	// If tty exists (unlikely in test), just cat?
	// Fallback to cat first file?
	f2, err := os.Open(fname)
	if err != nil {
		return err
	}
	defer f2.Close()
	_, err = io.Copy(cmd.OutOrStdout(), f2)
	return err
}
