{"command": "python3 <<'PY'
import subprocess, os
def ro(a, env=None, inp=None):
    e=os.environ.copy()
    if env: e.update(env)
    if isinstance(inp,str): inp=inp.encode()
    return subprocess.run(["./executable"]+a, input=inp, capture_output=True, env=e, timeout=10)
def rn(a, env=None, inp=None):
    e=os.environ.copy()
    if env: e.update(env)
    if isinstance(inp,str): inp=inp.encode()
    return subprocess.run(["/tmp/ov_new"]+a, input=inp, capture_output=True, env=e, timeout=10)
tests=[
    (["--debug","testdata/test.txt"], None, None),
    (["--debug","--config","ov.yaml","testdata/test.txt"], None, None),
    (["--debug","--config","nonexistent.yaml","testdata/test.txt"], None, None),
    (["--debug","--list-view-modes"], None, None),
    (["--debug","--completion","bash"], None, None),
    (["--debug","--version"], None, None),
    (["--config","ov.yaml","--list-view-modes"], None, None),
]
for a,inp,env in tests:
    p1=ro(a,inp,env); p2=rn(a,inp,env)
    print(f"{'OK' if (p1.stdout==p2.stdout and p1.stderr==p2.stderr and p1.returncode==p2.returncode) else 'DIFF'} {a} {repr(p1.stderr[:100])} vs {repr(p2.stderr[:100])}")
PY"}

